//! Actions-only current AccountManager/TLS/Common Info reception and all owned
//! stop/logout joins. No original SDK, Provider service, phone or device action.
use super::*;
pub(super) const BODY:&[u8]=br#"{"content":"original Info content","imdnId":"private-imdn","csnId":"private-csn","displayName":"private-display","userData":"private-not-public","OnlineMsg":"private-online","grant":true}"#;
fn info_config(root:&str,port:u16,timeout:u64,enabled:bool)->AccountConfig{let mut c=config(root,port,timeout);c.profile.native_receivers.as_mut().unwrap().im_messages.as_mut().unwrap().receive_info=enabled;c}
pub(super) fn info_packet(rpc:i32,index:i64,system:bool,body:&[u8])->Vec<u8>{
    let mut raw=Writer::new();raw.i64(index).unwrap();raw.i64(1234567890123).unwrap();raw.bytes(b"fixture-private-uid").unwrap();raw.bytes(if system{b"System.Info.Notice"}else{b"Info.Notice"}).unwrap();raw.bytes(body).unwrap();raw.properties(&[RpcProperty{key:b"../never-written",value:b"attachment-bytes"}]).unwrap();raw.properties(&[]).unwrap();
    let mut a=Writer::versioned().unwrap();a.bytes(n::im_data::MORE_MESSAGE_KIND).unwrap();a.properties(&[RpcProperty{key:b"Box",value:b"P2P/1_2"}]).unwrap();a.bytes(raw.finish().expose_to_transport()).unwrap();direct(rpc,n::rpc_incoming::ONLINE_MESSAGE_METHOD.as_bytes(),a.finish().expose_to_transport(),b"MessageReceiver",None)
}
pub(super) fn no_write_markers(db:&crate::platform::db::Database){let rows:i64=db.with_conn(|c|c.query_row("SELECT (SELECT COUNT(*) FROM app_voice_im_read_receipts)+(SELECT COUNT(*) FROM app_voice_im_user_reads)+(SELECT COUNT(*) FROM app_voice_im_read_status_actions)+(SELECT COUNT(*) FROM app_voice_im_outbox)",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(rows,0);}
pub(super) fn private_view(json:&str){for p in ["private-imdn","private-csn","private-display","private-not-public","private-online","fixture-private-uid","attachment-bytes","never-written","identity_key","box_id","info_epoch"]{assert!(!json.contains(p));}}
async fn login_host(peer:&mut CommonPeer){let p=peer.next().await.unwrap();let r=decode_request(&p[1..]).unwrap();assert_eq!(r.method,n::rpc_login::LOGIN_SESSION_METHOD.as_bytes());peer.send(&[reply(r.call_id,&login_result())]).await;let(_,flag)=hosting_call(peer).await;assert_eq!(flag,b"4");}
async fn batch_info(peer:&mut CommonPeer,db:&crate::platform::db::Database){
    let p=peer.next().await.unwrap();assert_eq!(p[0],0);let swap=decode_request(&p[1..]).unwrap();assert_eq!(swap.method,n::rpc_batch::SWAP_CALLS_METHOD.as_bytes());let mut r=Reader::versioned(swap.arguments).unwrap();assert_eq!(r.bytes().unwrap(),b"fixture-user");assert_eq!(r.bytes().unwrap(),b"fixture-original-selector");let payload=n::rpc_batch::read_payload(&mut r).unwrap();assert!(payload.requests.is_empty());assert!(payload.results.is_empty());
    let notice=hint(91,99,7);let body=info_packet(92,7,true,BODY);let notice=decode_request(&notice[1..]).unwrap();let body=decode_request(&body[1..]).unwrap();let mut w=Writer::new();w.boolean(true).unwrap();for word in [9,1,1,payload.fields[0],payload.fields[1],payload.fields[2]]{w.u32(word).unwrap();}w.u32(2).unwrap();
    for(seq,call)in[(1,&notice),(2,&body)]{w.i32(seq).unwrap();w.bytes(call.method).unwrap();w.bytes(call.arguments).unwrap();w.properties(&[RpcProperty{key:b"id",value:b"MessageReceiver"},RpcProperty{key:b"token",value:b"fixture-auth"}]).unwrap();}w.u32(0).unwrap();w.properties(&[]).unwrap();w.bytes(b"").unwrap();peer.send(&[reply(swap.call_id,w.finish().expose_to_transport())]).await;
    let mut seen=std::collections::BTreeSet::new();while seen.len()<2{let p=peer.next().await.unwrap();assert_eq!(p[0],0);let r=decode_request(&p[1..]).unwrap();assert_eq!(r.method,n::rpc_batch::SWAP_CALLS_METHOD.as_bytes());let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),b"fixture-user");assert_eq!(a.bytes().unwrap(),b"fixture-original-selector");let payload=n::rpc_batch::read_payload(&mut a).unwrap();assert!(payload.requests.is_empty());for(seq,done)in &payload.results{assert!([1,2].contains(seq));assert_eq!(done.result_stream,[0,1,0,0,0,0]);assert_eq!(count(db),1);seen.insert(*seq);}peer.send(&[reply(r.call_id,&n::runtime_backend::tests::swap_result(None,true,payload.fields))]).await;}
    // Same-FD DIRECT response follows the batch ACK in receive order and is a
    // processed-epoch barrier, not a peer-write-as-ACK assertion.
    peer.send(&[info_packet(95,7,true,BODY)]).await;next_reply(peer,95,true).await;assert_eq!(count(db),1);
}
async fn scenario(mode:u8){
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(info_config(&cert.root,port,if mode>=4{100}else{3000},mode!=5),100).await.unwrap().account;let line=account.line_id.clone();let db=temp.database.clone();
    let(go,wait)=tokio::sync::oneshot::channel();let(ready,observed)=tokio::sync::oneshot::channel();let(replay,wait_replay)=tokio::sync::oneshot::channel();let(done,finished)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{
        let mut peer=CommonPeer::open(listener,server).await;
        if mode==3{let p=peer.next().await.unwrap();let login=decode_request(&p[1..]).unwrap();peer.send(&[reply(login.call_id,&login_result()),hint(91,99,7),info_packet(92,7,false,BODY)]).await;
            loop{let p=peer.next().await.unwrap();assert_eq!(p[0],0,"early Info cannot be ACKed before Hosted");let r=decode_request(&p[1..]).unwrap();assert_eq!(r.method,n::rpc_batch::SWAP_CALLS_METHOD.as_bytes());let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),b"fixture-user");assert_eq!(a.bytes().unwrap(),b"fixture-original-selector");let payload=n::rpc_batch::read_payload(&mut a).unwrap();let seq=payload.requests.keys().copied().next();if seq.is_some(){tokio::time::sleep(Duration::from_millis(30)).await;assert_eq!(count(&db),0);}peer.send(&[reply(r.call_id,&n::runtime_backend::tests::swap_result(seq,true,payload.fields))]).await;if seq.is_some(){break;}}
            next_reply(&mut peer,92,true).await;next_reply(&mut peer,91,true).await;wait.await.unwrap();
        }else{login_host(&mut peer).await;wait.await.unwrap();match mode{
            0=>{peer.send(&[hint(91,99,7),info_packet(92,7,false,BODY)]).await;next_reply(&mut peer,92,true).await;next_reply(&mut peer,91,true).await;},
            1=>{peer.send(&[info_packet(91,7,false,BODY)]).await;next_reply(&mut peer,91,true).await;peer.send(&[hint(92,99,7)]).await;next_reply(&mut peer,92,true).await;},
            2=>batch_info(&mut peer,&db).await,
            4=>{peer.send(&[info_packet(91,7,false,br#"{"content":false}"#)]).await;next_reply(&mut peer,91,false).await;peer.send(&[hint(92,99,7)]).await;next_reply(&mut peer,92,false).await;},
            5=>{peer.send(&[info_packet(91,7,false,BODY)]).await;next_reply(&mut peer,91,false).await;peer.send(&[message(92,8,true)]).await;next_reply(&mut peer,92,true).await;peer.send(&[hint(93,99,7)]).await;next_reply(&mut peer,93,false).await;},
            6=>{for rpc in [91,92]{peer.send(&[info_packet(rpc,7,false,BODY)]).await;next_reply(&mut peer,rpc,true).await;}peer.send(&[info_packet(93,7,false,br#"{"content":"changed"}"#)]).await;next_reply(&mut peer,93,false).await;peer.send(&[hint(94,99,7)]).await;next_reply(&mut peer,94,true).await;},_=>panic!("fixture mode")}}
        assert_eq!(count(&db),i64::from(mode!=4));no_write_markers(&db);ready.send(()).unwrap();wait_replay.await.unwrap();
        if matches!(mode,0|1|6){peer.send(&[info_packet(97,7,false,BODY),hint(98,100,7)]).await;next_reply(&mut peer,97,true).await;next_reply(&mut peer,98,true).await;assert_eq!(count(&db),1);}
        done.send(()).unwrap();finish_account(&mut peer).await;
    }).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(async{while !manager.get(&line,100).await.unwrap().incoming_message_ready{tokio::task::yield_now().await;}}).await;go.send(()).unwrap();bounded(observed).await.unwrap();
    let rows=manager.im_messages(&line,16).unwrap();assert_eq!(rows.len(),usize::from(mode!=4));if let Some(row)=rows.first(){assert_eq!(row.text,if mode==5{"original IM text"}else{"original Info content"});assert_eq!(row.message_index,if mode==5{"8"}else{"7"});assert_eq!(row.kind,if mode==5{None}else{Some("info")});assert_eq!(row.info_type.as_deref(),if mode==5{None}else{Some("Notice")});assert_eq!(row.system_info,if mode==5{None}else{Some(mode==2)});private_view(&serde_json::to_string(&rows).unwrap());if matches!(mode,0|1|6){assert!(manager.delete_im_message(&line,row.id).unwrap());}}
    replay.send(()).unwrap();bounded(finished).await.unwrap();if matches!(mode,0|1|6){assert!(manager.im_messages(&line,16).unwrap().is_empty());}
    assert!(manager.messages(&line,16).unwrap().is_empty());assert!(temp.database.get_call_history_for_line(&line,16,0).unwrap().is_empty());no_write_markers(&temp.database);let view=manager.get(&line,100).await.unwrap();assert_eq!(view.phase,"hosted");assert!(!view.incoming_call_ready&&!view.outbound_authorized);
    let events=temp.database.get_recent_app_events(Some(&line),32).unwrap();assert_eq!(events.iter().filter(|e|e.event_type=="im.received").count(),usize::from(mode!=4));for e in events.iter().filter(|e|e.event_type=="im.received"){private_view(&e.payload_json);}
    assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());assert_eq!(manager.get(&line,100).await.unwrap().phase,"stopped");
}
#[tokio::test]async fn info_account_hint_waits_for_current_durable_info_then_original_reply_and_tombstone(){Box::pin(scenario(0)).await;}
#[tokio::test]async fn info_account_moremessage_before_hint_keeps_private_fields_and_independent_receipt(){Box::pin(scenario(1)).await;}
#[tokio::test]async fn info_account_batch_system_info_commits_before_both_original_results_and_processed_epoch(){Box::pin(scenario(2)).await;}
#[tokio::test]async fn info_account_early_info_retains_first_ticket_and_no_sql_before_original_hosting_ack(){Box::pin(scenario(3)).await;}
#[tokio::test]async fn info_account_invalid_structured_body_is_negative_without_message_or_new_sdk_grant(){Box::pin(scenario(4)).await;}
#[tokio::test]async fn info_account_default_false_nacks_info_but_preserves_original_text_and_healthy_sdk(){Box::pin(scenario(5)).await;}
#[tokio::test]async fn info_account_exact_duplicates_do_not_create_events_and_changed_body_is_negative(){Box::pin(scenario(6)).await;}
#[tokio::test]
async fn info_account_explicit_restart_cannot_ack_old_info_before_current_payload_and_joins_each_run(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(info_config(&cert.root,port,100,true),100).await.unwrap().account;let line=account.line_id.clone();let db=temp.database.clone();let(ready1,done1)=tokio::sync::oneshot::channel();let(ready2,done2)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let original=listener.into_std().unwrap();let second=TcpListener::from_std(original.try_clone().unwrap()).unwrap();let first=TcpListener::from_std(original).unwrap();
        let mut peer=CommonPeer::open(first,server.clone()).await;login_host(&mut peer).await;peer.send(&[info_packet(91,7,false,BODY)]).await;next_reply(&mut peer,91,true).await;ready1.send(()).unwrap();finish_account(&mut peer).await;
        let mut peer=CommonPeer::open(second,server).await;login_host(&mut peer).await;peer.send(&[hint(91,99,7)]).await;next_reply(&mut peer,91,false).await;assert_eq!(count(&db),1);
        peer.send(&[info_packet(92,7,false,BODY)]).await;next_reply(&mut peer,92,true).await;peer.send(&[hint(93,100,7)]).await;next_reply(&mut peer,93,true).await;assert_eq!(count(&db),1);ready2.send(()).unwrap();finish_account(&mut peer).await;
    }).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(done1).await.unwrap();let row=manager.im_messages(&line,16).unwrap().pop().unwrap();let old:String=temp.database.with_conn(|c|c.query_row("SELECT info_epoch FROM app_voice_im_messages",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert!(manager.delete_im_message(&line,row.id).unwrap());
    assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(done2).await.unwrap();
    let current:String=temp.database.with_conn(|c|c.query_row("SELECT info_epoch FROM app_voice_im_messages",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_ne!(old,current);assert!(manager.im_messages(&line,16).unwrap().is_empty());assert_eq!(temp.database.get_recent_app_events(Some(&line),16).unwrap().iter().filter(|e|e.event_type=="im.received").count(),1);no_write_markers(&temp.database);
    assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());
}).await;}
